217 | /** Parse an argument string using simple shell-style single and double quotes. */
218 | export function parseCommandArgs(argsString: string): string[] {
219 | 	const args: string[] = [];
220 | 	let current = "";
221 | 	let inQuote: string | null = null;
222 | 
223 | 	for (let i = 0; i < argsString.length; i++) {
224 | 		const char = argsString[i]!;
225 | 		if (inQuote) {
226 | 			if (char === inQuote) inQuote = null;
227 | 			else current += char;
228 | 		} else if (char === '"' || char === "'") {
229 | 			inQuote = char;
230 | 		} else if (char === " " || char === "\t") {
231 | 			if (current) {
232 | 				args.push(current);
233 | 				current = "";
234 | 			}
235 | 		} else {
236 | 			current += char;
237 | 		}
238 | 	}
239 | 	if (current) args.push(current);
240 | 	return args;
241 | }
