243 | /** Substitute prompt template placeholders (`$1`, `$@`, `$ARGUMENTS`, `${@:N}`, `${@:N:L}`) with command arguments. */
244 | export function substituteArgs(content: string, args: string[]): string {
245 | 	let result = content;
246 | 	result = result.replace(/\$(\d+)/g, (_, num: string) => args[parseInt(num, 10) - 1] ?? "");
247 | 	result = result.replace(/\$\{@:(\d+)(?::(\d+))?\}/g, (_, startStr: string, lengthStr?: string) => {
248 | 		let start = parseInt(startStr, 10) - 1;
249 | 		if (start < 0) start = 0;
250 | 		if (lengthStr) return args.slice(start, start + parseInt(lengthStr, 10)).join(" ");
251 | 		return args.slice(start).join(" ");
252 | 	});
253 | 	const allArgs = args.join(" ");
254 | 	result = result.replace(/\$ARGUMENTS/g, allArgs);
255 | 	result = result.replace(/\$@/g, allArgs);
256 | 	return result;
257 | }
